-- ── story 4-4a: client-arranged shipping capture ─────────────────────────
-- Generated by drizzle-kit (the courier_handovers table, the shipments and
-- attachments columns, the three dropped NOT NULLs and the nine indexes —
-- made IF NOT EXISTS by hand, the 6-2a lint) and hand-amended: the fail-fast
-- guard, the client backfill and its two assertions, every CHECK (drizzle-kit
-- is blind to them), the RLS policies and the post-migration probes
-- (`bun run db:generate` afterwards reports "No schema changes").
--
-- What changes:
--  * `shipments` gains `kind` (`carrier` | `client-label` | `courier-label`,
--    a constant default: metadata-only), `client_id` (BACKFILLED from orders
--    below and asserted complete — nullable in this release so an old api task
--    that inserts without it during the rolling deploy still works; SET NOT
--    NULL is a later migration, PENDING), the client label file, the courier
--    partner and its frozen snapshot, the parcel count, the handover, the
--    label verification triple, the void reason and the recording surface.
--    `carrier_connection_id`, `carrier_code` and `label_document_ref` lose NOT
--    NULL (a client-arranged shipment has no carrier connection). The status
--    vocabulary gains `handed_over`.
--  * `courier_handovers` is new: one courier, one client, one pickup.
--  * `attachments` widens (purposes, owners, PDF, the portal source) and
--    gains `doc_kind` and `page_count`.
--  * `email_messages` gains the `client-shipment-document` template and the
--    `stored-file` attachment kind; `client_contacts.email_events` gains
--    `shipment.documents`.
--  * `orders` gains `orders_ready_to_dispatch_idx` (A5).
--
-- Every shipments CHECK is added NOT VALID (the 0102 precedent: the table is
-- never scanned under the ACCESS EXCLUSIVE lock; new writes are checked). Each
-- new one is true of every existing row by construction — every existing row
-- is `kind = 'carrier'` with its connection, code and document set, and every
-- column the CHECKs read beside them is new (NULL). Their VALIDATE is PENDING,
-- beside 0102's. The status CHECK is re-added over a superset (asserted).
-- The attachments, email_messages and client_contacts CHECKs are re-added
-- validated: those tables are small (damage photos; mail rows purge at 90
-- days; contacts), and every existing row satisfies them by construction.
--
-- Lock cost and DEPLOY §5: the shipments backfill rewrites each row once
-- (one row per labelled order); the shipments, attachments and
-- courier_handovers builds are plain (small tables); `orders_ready_to_dispatch_idx`
-- names no new column, so on a large live `orders` it is pre-built
-- CONCURRENTLY by hand and skipped here by IF NOT EXISTS (the 0081 trick).
-- No foreign keys (IMPLEMENTATION-GUIDE §3).

-- ── 0. fail-fast: already applied, or out of order ──────────────────────
DO $$
BEGIN
	IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'courier_handovers') THEN
		RAISE EXCEPTION 'migration 0116: courier_handovers already exists — this migration has already been applied.';
	END IF;
	IF NOT EXISTS (
		SELECT 1 FROM information_schema.columns
		 WHERE table_schema = 'public' AND table_name = 'email_messages' AND column_name = 'attachment_kind'
	) THEN
		RAISE EXCEPTION 'migration 0116 is out of order: email_messages.attachment_kind does not exist — 0115 must be applied first.';
	END IF;
END $$;
--> statement-breakpoint
CREATE TABLE "courier_handovers" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"warehouse_id" uuid NOT NULL,
	"client_id" uuid NOT NULL,
	"code" text NOT NULL,
	"courier_partner_id" uuid,
	"courier_snapshot" jsonb,
	"courier_name" text NOT NULL,
	"pickup_person_name" text NOT NULL,
	"pickup_person_phone" text,
	"vehicle_number" text,
	"handed_over_at" timestamp with time zone NOT NULL,
	"shipment_count" integer NOT NULL,
	"package_count" integer NOT NULL,
	"cod_shipment_count" integer NOT NULL,
	"cod_total_paise" bigint NOT NULL,
	"client_snapshot" jsonb NOT NULL,
	"warehouse_snapshot" jsonb NOT NULL,
	"source" text NOT NULL,
	"device_id" uuid,
	"note" text,
	"created_by" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
