-- ── hand-amended: the client backfill (A1, D8) ───────────────────────────
UPDATE "shipments" s SET "client_id" = o."client_id"
  FROM "orders" o
 WHERE o."id" = s."order_id" AND o."tenant_id" = s."tenant_id" AND s."client_id" IS NULL;
--> statement-breakpoint
DO $$
DECLARE
	missing int;
	doubled int;
BEGIN
	SELECT count(*) INTO missing FROM "shipments" WHERE "client_id" IS NULL;
	IF missing > 0 THEN
		RAISE EXCEPTION 'migration 0116: % shipment(s) still have no client_id after the backfill — their order is missing.', missing;
	END IF;
	-- One live shipment per order, before the unique build below (4.6c's label
	-- guard already refused any second row, so this holds today).
	SELECT count(*) INTO doubled FROM (
		SELECT 1 FROM "shipments" WHERE "status" <> 'voided' GROUP BY "tenant_id", "order_id" HAVING count(*) > 1
	) d;
	IF doubled > 0 THEN
		RAISE EXCEPTION 'migration 0116: % order(s) have two non-voided shipments — void the extra first.', doubled;
	END IF;
END $$;
