-- ── hand-amended: §4 — every widened vocabulary keeps its old members ─────
DO $$
BEGIN
	IF EXISTS (SELECT 1 FROM unnest(ARRAY['labelled', 'manifested', 'voided']) AS old(v)
	           WHERE old.v <> ALL (ARRAY['labelled', 'manifested', 'voided', 'handed_over'])) THEN
		RAISE EXCEPTION 'migration 0116: the widened shipment status vocabulary lost a member.';
	END IF;
	IF EXISTS (SELECT 1 FROM unnest(ARRAY['receipt-damage']) AS old(v)
	           WHERE old.v <> ALL (ARRAY['receipt-damage', 'shipping-label', 'shipping-document', 'handover-sheet'])) THEN
		RAISE EXCEPTION 'migration 0116: the widened attachment purpose vocabulary lost a member.';
	END IF;
	IF EXISTS (SELECT 1 FROM unnest(ARRAY['goods_receipt_line']) AS old(v)
	           WHERE old.v <> ALL (ARRAY['goods_receipt_line', 'order', 'courier_handover'])) THEN
		RAISE EXCEPTION 'migration 0116: the widened attachment owner vocabulary lost a member.';
	END IF;
	IF EXISTS (SELECT 1 FROM unnest(ARRAY['image/jpeg', 'image/png', 'image/webp']) AS old(v)
	           WHERE old.v <> ALL (ARRAY['image/jpeg', 'image/png', 'image/webp', 'application/pdf'])) THEN
		RAISE EXCEPTION 'migration 0116: the widened attachment content-type vocabulary lost a member.';
	END IF;
	IF EXISTS (SELECT 1 FROM unnest(ARRAY['handheld', 'web']) AS old(v)
	           WHERE old.v <> ALL (ARRAY['handheld', 'web', 'portal'])) THEN
		RAISE EXCEPTION 'migration 0116: the widened attachment source vocabulary lost a member.';
	END IF;
	IF EXISTS (SELECT 1 FROM unnest(ARRAY['user-invite', 'password-reset', 'password-changed', 'client-receipt', 'client-dispatch']) AS old(v)
	           WHERE old.v <> ALL (ARRAY['user-invite', 'password-reset', 'password-changed', 'client-receipt', 'client-dispatch', 'client-shipment-document'])) THEN
		RAISE EXCEPTION 'migration 0116: the widened mail template vocabulary lost a member.';
	END IF;
	IF EXISTS (SELECT 1 FROM unnest(ARRAY['grn-pdf']) AS old(v)
	           WHERE old.v <> ALL (ARRAY['grn-pdf', 'stored-file'])) THEN
		RAISE EXCEPTION 'migration 0116: the widened attachment kind vocabulary lost a member.';
	END IF;
	IF EXISTS (SELECT 1 FROM unnest(ARRAY['receipt.recorded', 'order.dispatched']) AS old(v)
	           WHERE old.v <> ALL (ARRAY['receipt.recorded', 'order.dispatched', 'shipment.documents'])) THEN
		RAISE EXCEPTION 'migration 0116: the widened contact email-event vocabulary lost a member.';
	END IF;
END $$;
