-- ── the post-migration assertion (the 0095/0102 model) ───────────────────
-- Made-up uuids. Each shape is one valid row (`base`, a labelled client
-- label) with a per-probe override merged over it (`jsonb_populate_record`),
-- with a fresh id and order. The accepted shapes are inserted and rolled back
-- by a sentinel, so a CHECK that refused everything fails the migration; each
-- refused shape runs in its own subtransaction and must be refused BY ITS
-- NAMED CONSTRAINT — each violates only its target, or its target is the
-- first in name order (guide §3: CHECKs run in name order).
DO $$
DECLARE
	t uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	base jsonb;
	rec jsonb;
	refused_by text;
	probe record;
	shape record;
	unvalidated int;
BEGIN
	SELECT count(*) INTO unvalidated FROM pg_constraint
	 WHERE conrelid = 'public.shipments'::regclass AND contype = 'c' AND NOT convalidated
	   AND conname IN ('shipments_kind_check', 'shipments_status_check', 'shipments_carrier_arms', 'shipments_client_label_file',
	                   'shipments_status_by_kind', 'shipments_handover_pairing', 'shipments_verified_pairing',
	                   'shipments_package_count_range', 'shipments_courier_pairing', 'shipments_awb_shape',
	                   'shipments_void_reason', 'shipments_recorded_surface');
	IF unvalidated <> 12 THEN
		RAISE EXCEPTION 'migration 0116: expected the 12 shipments CHECKs present and NOT VALID, found % so.', unvalidated;
	END IF;
	base := jsonb_build_object(
		'tenant_id', t, 'warehouse_id', gen_random_uuid(), 'client_id', gen_random_uuid(),
