		('a verified carrier row', 'shipments_verified_pairing', '{"kind":"carrier","carrier_connection_id":"%R%","carrier_code":"sandbox","label_document_ref":"sandbox://probe","tracking_number":"SBX-PROBE-R","label_attachment_id":null,"recorded_surface":null,"label_verified_at":"2026-10-30T00:00:00Z","label_verified_by":"%U%","label_verify_method":"scan"}'),
