		('a void reason on a live row', 'shipments_void_reason', '{"void_reason":"x"}'),
		('a surface on a carrier row', 'shipments_recorded_surface', '{"kind":"carrier","carrier_connection_id":"%R%","carrier_code":"sandbox","label_document_ref":"sandbox://probe","tracking_number":"SBX-PROBE-R","label_attachment_id":null}'),
		('no surface on a client label', 'shipments_recorded_surface', '{"recorded_surface":null}'),
		('an unknown status', 'shipments_status_check', '{"status":"lost"}')
	) AS p(name, expected, override) LOOP
		refused_by := NULL;
		BEGIN
			rec := base || jsonb_build_object('id', gen_random_uuid(), 'order_id', gen_random_uuid())
				|| replace(replace(probe.override, '%U%', u::text), '%R%', gen_random_uuid()::text)::jsonb;
			INSERT INTO "shipments" SELECT (jsonb_populate_record(NULL::"shipments", rec)).*;
