			WHEN SQLSTATE 'P0116' THEN
				refused_by := NULL;
		END;
		IF refused_by IS DISTINCT FROM probe.expected THEN
			RAISE EXCEPTION 'migration 0116: shipment probe "%" was refused by % (expected %).', probe.name, coalesce(refused_by, 'nothing'), probe.expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "shipments" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0116: a shipment probe row survived.';
	END IF;
END $$;
