DECLARE
	t uuid := gen_random_uuid();
	c uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
BEGIN
	BEGIN
		INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","status","next_attempt_at","client_id","dedupe_key","priority","attachment_kind","attachment_ref")
		VALUES (gen_random_uuid(), t, 'client-shipment-document', 'a@example.in', '{}', 'pending', now(), c, 'client-shipment-document:a1:a@example.in', 1, 'stored-file', gen_random_uuid()),
		       (gen_random_uuid(), t, 'client-receipt', 'a@example.in', '{}', 'pending', now(), c, 'client-receipt:g1:a@example.in', 1, 'grn-pdf', gen_random_uuid());
		RAISE EXCEPTION USING ERRCODE = 'P0116', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation THEN
			RAISE EXCEPTION 'migration 0116: an accepted mail shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0116' THEN
			NULL;
	END;
	FOREACH probe IN ARRAY ARRAY[
		'a shipment document without its file',
		'stored-file on a receipt notice',
		'grn-pdf on a shipment document',
		'an unknown attachment kind',
		'a shipment document without a client'
	] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'a shipment document without its file' THEN 'email_messages_shipment_document_attachment'
			WHEN 'stored-file on a receipt notice' THEN 'email_messages_attachment_template_check'
			WHEN 'grn-pdf on a shipment document' THEN 'email_messages_attachment_template_check'
			WHEN 'an unknown attachment kind' THEN 'email_messages_attachment_kind_check'
			ELSE 'email_messages_client_shape_check'
		END;
		BEGIN
			INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","status","next_attempt_at","client_id","dedupe_key","priority","attachment_kind","attachment_ref")
			VALUES (
				gen_random_uuid(), t,
				CASE probe WHEN 'stored-file on a receipt notice' THEN 'client-receipt' ELSE 'client-shipment-document' END,
				'a@example.in', '{}', 'pending', now(),
				CASE probe WHEN 'a shipment document without a client' THEN NULL ELSE c END,
				'probe:x:a@example.in', 1,
				CASE probe
					WHEN 'a shipment document without its file' THEN NULL
					WHEN 'grn-pdf on a shipment document' THEN 'grn-pdf'
					WHEN 'an unknown attachment kind' THEN 'invoice-pdf'
					ELSE 'stored-file'
				END,
				CASE probe WHEN 'a shipment document without its file' THEN NULL ELSE gen_random_uuid() END
			);
			RAISE EXCEPTION USING ERRCODE = 'P0116', MESSAGE = 'a refused probe landed';
		EXCEPTION
			WHEN check_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			WHEN SQLSTATE 'P0116' THEN
				RAISE EXCEPTION 'migration 0116: the mail probe "%" was accepted.', probe;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0116: the mail probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "email_messages" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0116: a mail probe row survived.';
	END IF;
END $$;
